import { describe, it, expect, vi } from "vitest";
import {
  rollingAdmission,
  budgets,
  consumeBudgets,
  RateLimitUnavailable,
  rateLimitHttpError,
  RateLimitError,
} from "@/lib/rate-limit";
const owner = "11111111-1111-4111-8111-111111111111";
describe("strict rolling limits", () => {
  it("admits exactly the allowance and excludes the exact expiry boundary", () => {
    const now = new Date("2026-10-20T00:00:00Z"),
      budget = budgets.checkout;
    let times: Date[] = [];
    for (let i = 0; i < 5; i++) {
      const r = rollingAdmission(times, now, budget);
      expect(r.admitted).toBe(true);
      times = r.times;
    }
    expect(rollingAdmission(times, now, budget)).toMatchObject({
      admitted: false,
      retryAfter: 600,
    });
    expect(
      rollingAdmission(times, new Date(+now + 599999), budget),
    ).toMatchObject({ admitted: false, retryAfter: 1 });
    expect(
      rollingAdmission(times, new Date(+now + 600000), budget),
    ).toMatchObject({ admitted: true });
  });
  it("does not reset at a calendar minute boundary", () => {
    const now = new Date("2026-10-20T00:00:59Z");
    expect(
      rollingAdmission(
        Array.from({ length: 10 }, () => now),
        new Date(+now + 1001),
        budgets.billingManagement,
      ),
    ).toMatchObject({ admitted: false, retryAfter: 59 });
  });
  it("fails closed on database failure with safe errors and HTTP metadata", async () => {
    const client = {
      $transaction: vi.fn().mockRejectedValue(new Error("private-token")),
    };
    await expect(
      consumeBudgets(owner, ["campaign"], client as never),
    ).rejects.toBeInstanceOf(RateLimitUnavailable);
    const response = rateLimitHttpError(new RateLimitError(127))!;
    expect(response.status).toBe(429);
    expect(response.headers.get("Retry-After")).toBe("127");
    expect(rateLimitHttpError(new RateLimitUnavailable())!.status).toBe(503);
  });
});
